{
  "name": "utt-opencode",
  "version": "0.1.1",
  "type": "module",
  "description": "Voice dictation for OpenCode: talk to your coding agent, words appear in the prompt as you speak. An extension for utt, on-device speech-to-text for macOS.",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "utt",
    "speech-to-text",
    "voice-input",
    "dictation",
    "voice-coding",
    "voice-typing",
    "macos",
    "on-device",
    "local-first",
    "offline",
    "parakeet",
    "whisper",
    "ai-coding-agent",
    "coding-agent",
    "tui",
    "privacy",
    "transcription"
  ],
  "homepage": "https://utt.jurrejan.com/extensions/opencode/",
  "bugs": "https://github.com/doublej/utt-opencode/issues",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/doublej/utt-opencode.git"
  },
  "os": [
    "darwin"
  ],
  "exports": {
    "./tui": "./dist/tui.js",
    "./package.json": "./package.json"
  },
  "files": [
    "LICENSE",
    "dist"
  ],
  "scripts": {
    "build": "bun build.ts",
    "prepack": "bun build.ts",
    "check": "tsc --noEmit",
    "test": "bun test"
  },
  "peerDependencies": {
    "@opencode/plugin": ">=2.0.31",
    "@opentui/core": ">=0.5.17",
    "@opentui/solid": ">=0.5.17",
    "solid-js": ">=1.9.0"
  },
  "peerDependenciesMeta": {
    "@opencode/plugin": {
      "optional": true
    },
    "@opentui/core": {
      "optional": true
    },
    "@opentui/solid": {
      "optional": true
    },
    "solid-js": {
      "optional": true
    }
  },
  "devDependencies": {
    "@opencode/plugin": "2.0.31",
    "@opencode/theme": "2.0.31",
    "@opentui/core": "0.5.17",
    "@opentui/solid": "0.5.17",
    "bun-types": "^1.3.0",
    "solid-js": "^1.9.17",
    "typescript": "^5.6.0"
  }
}
